cat > "$TMPDIR/x.py" 2>/dev/null; python - <<'PYEOF'
import re, subprocess, sys

LIVE = ["js/app.js","js/router.js","js/api.js","js/components/index.js",
        "js/pages/about.js","js/pages/contacts.js","js/pages/home.js",
        "js/pages/portfolio.js","js/pages/prices.js","js/pages/services.js",
        "index.html"]

# quoted string literals: '...' and "..."
lit = re.compile(r"'((?:[^'\\\n]|\\.)*)'|\"((?:[^\"\\\n]|\\.)*)\"")

def strings(text):
    out=[]
    for m in lit.finditer(text):
        s = m.group(1) if m.group(1) is not None else m.group(2)
        out.append(s)
    return out

def base(p):
    return subprocess.run(["git","show","2742368:"+p],capture_output=True,text=True,encoding="utf-8").stdout

def cur(p):
    return open(p,encoding="utf-8").read()

bad=0
for p in LIVE:
    b=strings(base(p)); c=strings(cur(p))
    from collections import Counter
    cb,cc=Counter(b),Counter(c)
    removed=cb-cc; added=cc-cb
    if removed or added:
        bad=1
        print("### DIFF in",p)
        for s,n in sorted(removed.items()): print("  -",n,repr(s))
        for s,n in sorted(added.items()): print("  +",n,repr(s))
    else:
        print("OK (identical string literals):",p)
print("\nRESULT:", "DIFFERENCES FOUND" if bad else "ALL LIVE STRING LITERALS IDENTICAL")
PYEOF

export PYTHONIOENCODING=utf-8; python - <<'PYEOF'
import re, subprocess, io, sys
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')
def base(p):
    return subprocess.run(["git","show","2742368:"+p],capture_output=True).stdout.decode("utf-8")

# extract object-literal string VALUES  key: 'value'  and >${..}< text
val = re.compile(r"[:,]\s*'((?:[^'\\]|\\.)*)'")
def vals(t): return set(m.group(1) for m in val.finditer(t))

live_now  = vals(open("js/components/index.js",encoding="utf-8").read())
live_base = vals(base("js/components/index.js"))
dead = set()
for f in ["js/components/header.js","js/components/footer.js","js/components/serviceCard.js"]:
    dead |= vals(base(f))

print("live index.js baseline == live index.js now :", live_base == live_now)
print("strings unique to the DELETED dead files (not present in live index.js):")
orphan = dead - live_now
for s in sorted(orphan): print("   ", repr(s))
if not orphan: print("    (none — every dead-file string also exists in the live file)")
PYEOF

